// ?Rva009B60E0BuildTree@@YAXPAURva009B60E0Output@@PAHH@Z
// partial score=0.65 date=2026-09-10
// cl: /O2 /DNDEBUG /DWIN32 /D_WINDOWS /MD

/*
 * VP6 Huffman-tree construction at retail RVA 0x009B60E0.
 *
 * The decoder siblings at 0x009B62A0 and 0x009B6320 establish the packed
 * child format used here.  The three direct VP6 callers (9AB36F, 9AB3F8 and
 * 9AB49F) pass an output table, a 128-entry frequency table and its count.
 * Retail keeps the nodes in a stable, ascending-weight linked list and
 * appends one internal node per merge.  Zero frequencies are promoted to
 * one before sorting, and the first child's probability is firstWeight*256 /
 * totalWeight.
 */

struct Rva009B60E0PackedChild
{
	unsigned leaf:1;
	unsigned index:7;
};

struct Rva009B60E0Output
{
	Rva009B60E0PackedChild left;
	Rva009B60E0PackedChild right;
	unsigned char probability;
};

struct Rva009B60E0Entry
{
	int next;
	int weight;
	Rva009B60E0PackedChild child;
};

typedef char Rva009B60E0PackedChild_size_must_be_4[
	(sizeof(Rva009B60E0PackedChild) == 4) ? 1 : -1];
typedef char Rva009B60E0Output_size_must_be_12[
	(sizeof(Rva009B60E0Output) == 12) ? 1 : -1];

void Rva009B60E0BuildTree(Rva009B60E0Output *output, int *frequencies, int count)
{
	Rva009B60E0Entry entries[64];
	Rva009B60E0Entry *newEntry;
	int head = 0;
	int root = count - 1;
	int i;

	Rva009B60E0Entry *entry = entries;
	for (i = 0; i < count; ++i, ++entry)
	{
		entry->child.index = i;
		entry->child.leaf = 1;
		if (frequencies[i] == 0)
			frequencies[i] = 1;
		entry->weight = frequencies[i];
		entry->next = -1;
	}

	int freeEntry = count;
	Rva009B60E0Entry *candidate = entries + 1;
	for (i = 1; i < count; ++i, ++candidate)
	{
		int cursor = head;
		int previous = head;
		while (cursor != -1 && candidate->weight > entries[cursor].weight)
		{
			previous = cursor;
			cursor = entries[cursor].next;
		}
		if (cursor == head)
			head = i;
		else
			entries[previous].next = i;
		candidate->next = cursor;
	}

	newEntry = entries + i;
	Rva009B60E0Output *destination = output + root;
	while (entries[head].next != -1)
	{
		int first = head;
		int second = entries[first].next;
		int firstWeight = entries[first].weight;
		int weight = firstWeight + entries[second].weight;

		--destination;
		destination->left = entries[first].child;
		destination->right = entries[second].child;
		newEntry->weight = weight;
		newEntry->next = -1;
		destination->probability = (unsigned char)((firstWeight << 8) / weight);

		--root;
		newEntry->child.index = root;
		newEntry->child.leaf = 0;
		head = entries[second].next;
		int cursor = head;
		int previous = head;
		while (cursor != -1 && weight > entries[cursor].weight)
		{
			previous = cursor;
			cursor = entries[cursor].next;
		}
		if (cursor == head)
			head = freeEntry;
		else
			entries[previous].next = freeEntry;
		newEntry->next = cursor;
		++freeEntry;
		++newEntry;
	}
}
